<?php require_once 'includes/admin_common.php';
$type=strtolower($_GET['type']??'csv'); $q=trim($_GET['q']??''); $where='';$types='';$params=[]; if($q!==''){$where=' WHERE name LIKE ? OR username LIKE ? OR email LIKE ? OR role LIKE ? OR class LIKE ?';$like="%$q%";$types='sssss';$params=[$like,$like,$like,$like,$like];} $rows=fetch_all('SELECT id,name,username,email,class,role,created_at,is_logged_in,failed_attempts,lock_until,last_login FROM ustads'.$where.' ORDER BY created_at DESC',$types,$params);
if($type==='print'){ ?><!doctype html><html><head><meta charset="utf-8"><title>Ustads Report</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{padding:30px}.report-head{border-bottom:3px solid #635bff;margin-bottom:20px}</style></head><body><div class="report-head"><h1>Ustads Report</h1><p>Generated <?= e(date('Y-m-d H:i')) ?></p></div><table class="table table-bordered table-striped"><thead><tr><?php foreach(['ID','Name','Username','Email','Class','Role','Created','Login','Failed','Lock Until','Last Login'] as $h): ?><th><?= e($h) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($r as $v): ?><td><?= e($v) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table><script>window.print()</script></body></html><?php exit; }
$filename='ustads_export_'.date('Ymd_His').($type==='excel'?'.xls':'.csv'); header('Content-Type: '.($type==='excel'?'application/vnd.ms-excel':'text/csv').'; charset=utf-8'); header('Content-Disposition: attachment; filename='.$filename); $out=fopen('php://output','w'); fputcsv($out,['ID','Name','Username','Email','Class','Role','Created','Is Logged In','Failed Attempts','Lock Until','Last Login']); foreach($rows as $r) fputcsv($out,$r); fclose($out); exit;
